SELECT * FROM ( SELECT m.*, ROWNUM AS rn FROM ( SELECT member_no, member_id, name, nick_name, email, phone_number, created_at, purchase_count, status FROM member
AND status = #{status}
AND (member_id LIKE '%' || #{keyword} || '%' OR name LIKE '%' || #{keyword} || '%')
ORDER BY created_at DESC ) m WHERE ROWNUM <= #{endRow} ) WHERE rn >= #{startRow}

