mapper.insert:
INSERT INTO member_coupon (member_coupon_no, member_no, coupon_no, used_yn, issued_at, start_at, end_at)
SELECT seq_member_coupon.NEXTVAL, #{memberNo}, #{couponNo}, 'N', SYSTIMESTAMP, #{startAt}, #{endAt}
